import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"多期风险预算","description":"","frontmatter":{"title":"多期风险预算","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/multi-period-risk-budget.md","filePath":"quant/multi-period-risk-budget.md","lastUpdated":1789023840000}'),p={name:"quant/multi-period-risk-budget.md"};function u(A,a,m,B,c,_){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="多期风险预算" tabindex="-1">多期风险预算 <a class="header-anchor" href="#多期风险预算" aria-label="Permalink to &quot;多期风险预算&quot;">​</a></h1><div class="epigraph"><p>单期风险预算把限额写在当下的因子暴露上；多期还要管路径：何时用完预算、回撤后如何再分配。</p><footer>—— 对照 Grinold–Kahn 对主动风险预算的论述；动态风险预算见机构组合管理实务</footer></div><p><a href="/quant/tax-aware-portfolio">上一课</a>把税写进再平衡。风险预算主干 <a href="/quant/risk-budgeting">风险预算</a> 是单期分解。缺口是<strong>时间</strong>：年度主动风险预算 3%，若一季度用完，后三季度是停机还是加预算？本课写多期分配与回撤依赖的政策，接到目标日期。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Grinold–Kahn 的 IR 优化给出各账面的主动风险份额。那是静态。真实约束是：董事会给的是年度跟踪误差或 VaR 预算，路径上已实现主动风险会消耗预算。政策若「用完即停」，等于在最有信号的时候关掉 alpha，并把卖出冲击集中在坏时候。问题是把预算当成<strong>需要跨期平滑的资源</strong>，类似 GP 把交易平滑，而不是当成每日硬帽。</p><p>回撤规则：净值跌破阈值降杠杆，会在均值回复的策略上买在高点、卖在低点。要区分：风险预算（事前 \\(\\sigma\\)）与止损（事后路径）。两者都要，不能互相替代。</p><h3 id="预算消耗不是线性时钟" tabindex="-1">预算消耗不是线性时钟 <a class="header-anchor" href="#预算消耗不是线性时钟" aria-label="Permalink to &quot;预算消耗不是线性时钟&quot;">​</a></h3><p>若收益接近白噪声，已实现方差随时间线性涨，预算可按剩余日历比例。若波动聚集，早季的冲击会预支全年。应用条件 vol（<a href="/quant/har-rv">HAR</a>/GARCH）把预算写成「剩余积分方差」而不是剩余月份。</p><p><span class="marginnote">多策略共享预算时，要避免每个策略各自 3% 再线性加总。相关性使总风险不是和；多期还要管策略间的占用先后。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事前：把年度 \\(\\sigma\\) 预算换成每日风险单位，用条件 vol 缩放目标暴露，见 <a href="/quant/vol-scale-cta">波动瞄准</a> 精神，但对象是主动簿。消耗：跟踪已实现主动方差积分，接近上限时降低增益 \\(A\\)（GP）或加宽再平衡带，而不是二元开关。回撤：独立的财富状态，降 \\(\\gamma\\) 或降杠杆，规则公开、避免优化到历史回撤。报告：预算使用率、条件 vol、因子占用三张表。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>风险预算是对未来二次变差的配额。多期最优类似消费-储蓄：今天多用，明天少用。信号强（IR 高）时应允许暂时超用并在弱信号期补偿——这需要治理，不是交易员临时申请。没有治理，多期优化会变成事后为超限找的借口。</p>',13)),(e(),s(h,null,{default:r(()=>[E(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Ann%5B%22%E5%B9%B4%E5%BA%A6%E4%B8%BB%E5%8A%A8%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%22%5D%20--%3E%20Cond%5B%22%E6%9D%A1%E4%BB%B6%20vol%20%E6%8D%A2%E6%88%90%E6%AF%8F%E6%97%A5%E5%8D%95%E4%BD%8D%22%5D%0A%20%20Cond%20--%3E%20Use%5B%22%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%96%B9%E5%B7%AE%E6%B6%88%E8%80%97%22%5D%0A%20%20Use%20--%3E%20Smooth%5B%22%E6%8E%A5%E8%BF%91%E4%B8%8A%E9%99%90%E5%88%99%E9%99%8D%E5%A2%9E%E7%9B%8A%20%E9%9D%9E%E5%BC%80%E5%85%B3%22%5D%0A%20%20DD%5B%22%E5%9B%9E%E6%92%A4%E7%8A%B6%E6%80%81%22%5D%20--%3E%20Lev%5B%22%E7%8B%AC%E7%AB%8B%E9%99%8D%E6%9D%A0%E6%9D%86%E8%A7%84%E5%88%99%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>董事会预算往往不可平滑（硬帽）。硬帽下只能留缓冲，缓冲是成本。策略相关突变使「已分配预算」瞬间不够，要有集中超限预案。本课不把风险预算写成保证回撤上限——VaR 预算管的是事前 \\(\\sigma\\)，不是路径最大回撤。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多期预算管理的是风险路径，不是把单期限额每天重贴一次。</li><li>用条件 vol 与平滑降增益，避免用完停机。</li><li>回撤规则与预算分开；共享预算要管相关。</li><li>出处：Grinold and Kahn, <em>Active Portfolio Management</em>；波动瞄准与机构风险预算实务。</li></ul>',4))])}const D=i(p,[["render",u]]);export{q as __pageData,D as default};
